import{_ as n,C as a,o,c as i,ag as s,E as r}from"./chunks/framework.CtWPcAmt.js";const w=JSON.parse('{"title":"Seller Registration & Sign-in","description":"","frontmatter":{},"headers":[],"relativePath":"sellers/seller-registration.md","filePath":"sellers/seller-registration.md","lastUpdated":1787563966000}'),l={name:"sellers/seller-registration.md"};function g(d,e,h,c,p,m){const t=a("ImagePopup");return o(),i("div",null,[e[0]||(e[0]=s('<h1 id="seller-registration-sign-in" tabindex="-1">Seller Registration &amp; Sign-in <a class="header-anchor" href="#seller-registration-sign-in" aria-label="Permalink to &quot;Seller Registration &amp; Sign-in&quot;">​</a></h1><p>Before a seller can do anything else they have to join the marketplace and get in. This page covers the three screens that surround the Seller Panel — becoming a seller, signing in, and recovering a password — and what the admin controls about each.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How someone becomes a seller</li><li>What happens between registering and being able to sell</li><li>How signing in and password recovery work</li></ul></div><h2 id="becoming-a-seller" tabindex="-1">Becoming a seller <a class="header-anchor" href="#becoming-a-seller" aria-label="Permalink to &quot;Becoming a seller&quot;">​</a></h2><p>A visitor starts from the <strong>Become Seller</strong> form. The quickest route is the button on the <a href="/storefront/marketplace-landing-page">marketplace landing page</a>, whose caption the admin sets.</p><p>The <strong>Become Seller</strong> form opens with the account basics — <strong>Name</strong>, <strong>Email</strong>, <strong>Slug</strong>, <strong>Password</strong> and <strong>Confirm Password</strong> — where the slug becomes the address of the seller&#39;s public store page.</p><p>Below them sits an <strong>Additional Information</strong> section built from the <a href="/sellers/seller-attributes">seller attributes</a> the admin marked as visible on sign up, starting with <strong>Business Name</strong>. That section is how you decide what a new seller must tell you: mark an attribute visible on sign up and it appears here for everyone who registers next.</p>',7)),r(t,{src:"/images/seller-registration/become-seller.png",alt:"Become Seller form showing the name, email, slug and password fields above the Additional Information section"}),e[1]||(e[1]=s('<p>Select <strong>Register</strong>. The account is created, and the seller is returned to the sign-in screen.</p><div class="info custom-block"><p class="custom-block-title">Approval decides what happens next</p><p>Under <strong>Configure → Marketplace → Sellers → Registration &amp; Visibility</strong>, <strong>Approval Required</strong> decides whether a new seller can sell straight away. With it on, the account is created unapproved and the seller is told their activation seeks admin approval until you approve them under <strong>Marketplace → Sellers</strong>. With it off, they can sign in and start listing immediately. See <a href="/sellers/seller-management">Seller Management</a>.</p></div><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>The <strong>Seller Login</strong> screen takes an <strong>Email</strong> and <strong>Password</strong>, with a <strong>Show Password</strong> control if the seller wants to check what they typed. Alongside it are <strong>Forgot Password?</strong> and, for anyone who hasn&#39;t joined yet, <strong>New seller? Create your account</strong>.</p>',4)),r(t,{src:"/images/seller-registration/seller-login.png",alt:"Seller Login screen with email, password, Forgot Password and Create your account links"}),e[2]||(e[2]=s('<p>Three things can stop a sign-in, and each says which:</p><ul><li><strong>Wrong details</strong> — the seller is asked to check their credentials and try again.</li><li><strong>Not yet approved</strong> — the seller is told their activation seeks admin approval.</li><li><strong>Suspended</strong> — the seller is told their account has been suspended and to contact the admin. Suspension is a toggle on the seller&#39;s admin edit form.</li></ul><p>Once in, the seller lands on the <a href="/sellers/seller-dashboard">Dashboard</a>.</p><h2 id="recovering-a-password" tabindex="-1">Recovering a password <a class="header-anchor" href="#recovering-a-password" aria-label="Permalink to &quot;Recovering a password&quot;">​</a></h2><p><strong>Recover Password</strong> takes the seller&#39;s email address and sends a reset link.</p><ul><li>If the address isn&#39;t registered, the screen says no user could be found with it.</li><li>If a link has already gone out, the seller is told so rather than sent a second one — one reset request per hour.</li><li>A reset link stays valid for <strong>one hour</strong>.</li></ul><p>The link opens <strong>Reset Password</strong>, which shows the <strong>Registered Email</strong> and asks for a new <strong>Password</strong> and <strong>Confirm Password</strong>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep the sign-up form short. Every attribute you mark visible on sign up is one more thing standing between an interested seller and a created account — anything you can collect later belongs on <a href="/sellers/seller-profile">Manage Profile</a> instead.</p></div>',8))])}const f=n(l,[["render",g]]);export{w as __pageData,f as default};
